package com.example.discussions.controller;import com.example.discussions.dto.Responses.*;import com.example.discussions.exception.ApiException;import com.example.discussions.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;@RestController @RequestMapping("/api/users") @Transactional(readOnly=true) public class UserController{private final UserRepository users;private final DiscussionRepository discussions;private final VoteRepository votes;public UserController(UserRepository u,DiscussionRepository d,VoteRepository v){users=u;discussions=d;votes=v;}@GetMapping("/{username}")public Profile profile(@PathVariable String username){var u=users.findByUsernameIgnoreCase(username).orElseThrow(()->ApiException.notFound("Пользователь не найден"));var list=discussions.findAll().stream().filter(d->d.author.id.equals(u.id)).map(d->DiscussionView.of(d,votes.countByDiscussion(d),false)).toList();return new Profile(u.id,u.username,u.displayName,u.bio,u.role.name(),u.createdAt,list);}}
